package dto

// AssetValidationCreate describes a gateway-managed human portrait validation.
// Callback URLs are generated by the server, never chosen by a caller.
type AssetValidationCreate struct {
	ProjectName    string `json:"ProjectName"`
	Name           string `json:"Name"`
	Description    string `json:"Description"`
	ChannelID      int    `json:"ChannelId"`
	IdempotencyKey string `json:"IdempotencyKey"`
}

// AssetValidationSummary deliberately excludes links and upstream credentials.
type AssetValidationSummary struct {
	SessionID      string        `json:"SessionId"`
	Status         string        `json:"Status"`
	GroupID        string        `json:"GroupId,omitempty"`
	ExpiresAt      int64         `json:"ExpiresAt"`
	Name           string        `json:"Name"`
	ChannelID      int           `json:"ChannelId"`
	CanPoll        bool          `json:"CanPoll"`
	NextPollAt     int64         `json:"NextPollAt,omitempty"`
	Error          *AssetFailure `json:"Error,omitempty"`
	CanContinue    bool          `json:"CanContinue"`
	ContinueError  *AssetFailure `json:"ContinueError,omitempty"`
	NeedsReview    bool          `json:"NeedsReview"`
	BindingPending bool          `json:"BindingPending"`
	CanArchive     bool          `json:"CanArchive"`
	ArchivedAt     int64         `json:"ArchivedAt"`
	CreatedAt      int64         `json:"CreatedAt"`
	LastCheckedAt  int64         `json:"LastCheckedAt"`
	ChannelName    string        `json:"ChannelName,omitempty"`
	ProjectName    string        `json:"ProjectName"`
}

// BytedToken is an opaque local session identifier, not the provider token.
// Links may only be disclosed to an authenticated actor with asset:write.
type AssetValidationView struct {
	BytedToken     string        `json:"BytedToken"`
	H5Link         string        `json:"H5Link,omitempty"`
	CallbackURL    string        `json:"CallbackURL,omitempty"`
	Status         string        `json:"Status"`
	GroupID        string        `json:"GroupId,omitempty"`
	ExpiresAt      int64         `json:"ExpiresAt"`
	Name           string        `json:"Name"`
	ChannelID      int           `json:"ChannelId"`
	CanPoll        bool          `json:"CanPoll"`
	NextPollAt     int64         `json:"NextPollAt,omitempty"`
	Error          *AssetFailure `json:"Error,omitempty"`
	CanContinue    bool          `json:"CanContinue"`
	ContinueError  *AssetFailure `json:"ContinueError,omitempty"`
	NeedsReview    bool          `json:"NeedsReview"`
	BindingPending bool          `json:"BindingPending"`
	CanArchive     bool          `json:"CanArchive"`
	ArchivedAt     int64         `json:"ArchivedAt"`
	CreatedAt      int64         `json:"CreatedAt"`
	LastCheckedAt  int64         `json:"LastCheckedAt"`
	ChannelName    string        `json:"ChannelName,omitempty"`
	ProjectName    string        `json:"ProjectName"`
}

type AssetValidationRecordFilter struct {
	Page     int
	PageSize int
	Name     string
	Status   string
	Archived string
}

type AssetValidationRecords struct {
	Items        []AssetValidationSummary `json:"Items"`
	TotalCount   int64                    `json:"TotalCount"`
	PendingCount int64                    `json:"PendingCount"`
	Page         int                      `json:"Page"`
	PageSize     int                      `json:"PageSize"`
}

type AssetValidationArchive struct {
	ProjectName string   `json:"ProjectName"`
	SessionIDs  []string `json:"SessionIds"`
	Archived    *bool    `json:"Archived"`
}

type AssetValidationChannel struct {
	ID   int    `json:"Id"`
	Name string `json:"Name"`
}
